 {page === "reminders"&&<Reminders data={data} now={now} onBooking={b=>setModal({type:"bookingDetail",item:b})} onSource={r=>{setSourceRecord(r);go(r.source_id?"rentals":"sales");}} onAll={()=>{}}/>}
