function Stat({ label, value, note, icon: Icon, color = "teal" }: {
    label: string;
    value: string | number;
    note: string;
    icon: any;
    color?: string;
}) { const { t: tr, language, formatDate } = useLanguage(); return <div className="stat-card panel"><div className="stat-top"><span>{label}</span><span className={`stat-icon ${color}`}><Icon size={19} strokeWidth={1.8}/></span></div><strong className="stat-value">{value}</strong><small>{note}</small></div>; }
function PanelHeading({ title, subtitle, action, onClick }: {
    title: string;
    subtitle?: string;
    action?: string;
    onClick?: () => void;
}) { const { t: tr, language, formatDate } = useLanguage(); return <div className="panel-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action && <button className="text-btn" onClick={onClick}>{action}<ArrowUpRight size={15}/></button>}</div>; }
function Detail({ label, value }: {
    label: string;
    value?: string;
}) { const { t: tr, language, formatDate } = useLanguage(); return <div className="detail-item"><small>{label}</small><strong>{value || "—"}</strong></div>; }
function InfoMark() { const { t: tr, language, formatDate } = useLanguage(); return <span className="info-mark">i</span>; }
function modalTitle(type: string, item: Row | undefined, tr: (s: string) => string) { const titles: Row = { customer: item ? tr("Ubah customer") : tr("Tambah customer"), unit: item ? tr("Ubah unit motor") : tr("Tambah unit motor"), booking: tr("Buat booking"), payment: tr("Catat pembayaran"), note: tr("Tambah catatan"), noteUpdate: tr("Tindak lanjut catatan"), feedback: tr("Catat feedback customer"), promotion: tr("Tambah promo disetujui"), staff: item?tr("Ubah user"):tr("Tambah user"), extend: tr("Perpanjang booking"), reschedule: tr("Ubah tanggal booking"), cancel: tr("Batalkan booking"), confirm: tr("Konfirmasi booking"), bookingDetail: tr("Detail booking"), unitDetail: tr("Detail unit motor"), customerDetail: tr("Profil customer"), noteDetail: item?.title || tr("Detail catatan"), evidence: tr("Bukti serah terima"), handover: item?.kind === "in" ? tr("Motor kembali") : tr("Motor keluar"), install: tr("Pasang aplikasi"), disablePromo: tr("Nonaktifkan promo") }; return titles[type] || "Werigo Ops"; }
function unitService(bookings: Row[], unitId: string, start: number, end: number) { return bookings.reduce((sum, b) => { const ids = JSON.parse(b.unit_ids) as string[], index = ids.indexOf(unitId); if (index < 0)
    return sum; const amount = allocatedRental(b, start, end), snap = JSON.parse(b.pricing_snapshot), weights = ids.map((_, i) => snap.lines?.[i]?.amount || 1), all = weights.reduce((s: number, n: number) => s + n, 0); const before = weights.slice(0, index).reduce((s: number, n: number) => s + n, 0); return sum + Math.round(amount * (before + weights[index]) / all) - Math.round(amount * before / all); }, 0); }
function auditLabel(action: string, tr: (s: string) => string) { const map: Row = { "customers.created": tr("Customer ditambahkan"), "customer.updated": tr("Customer diperbarui"), "units.created": tr("Unit ditambahkan"), "unit.updated": tr("Unit diperbarui"), "bookings.created": tr("Booking dibuat"), "booking.confirmed": tr("Booking dikonfirmasi"), "booking.extended": tr("Booking diperpanjang"), "booking.cancelled": tr("Booking dibatalkan"), "payments.created": tr("Pembayaran dicatat"), "handover.out": tr("Motor keluar dicatat"), "handover.in": tr("Motor kembali dicatat"), "notes.created": tr("Catatan ditambahkan"), "note.updated": tr("Catatan ditindaklanjuti"), "feedback.created": tr("Feedback dicatat"), "promotions.created": tr("Promo dicatat"), "promotion.disabled": tr("Promo dinonaktifkan"), "staff.updated": tr("Akses staf diperbarui"),"sales.imported":tr("Data sales diimpor"),"sales.followup":tr("Pengembalian sumber ditindaklanjuti") }; return map[action] || action; }
function BookingCalendar({ data, onOpen }: {
    data: Row;
    onOpen: (b: Row) => void;
}) {const renderTime=useOpsClock(); const { t: tr, language, formatDate } = useLanguage(); const [start, setStart] = useState(parseWita(dateWita(renderTime) + "T00:00")); const days = Array.from({ length: 14 }, (_, i) => start + i * DAY); return <section className="panel calendar-panel"><div className="panel-heading"><div><h2>{tr("Kalender setiap motor")}</h2><p>{dateWita(start)} — {dateWita(start + 13 * DAY)}{tr(" \u00B7 Geser ke samping untuk melihat 14 hari")}</p></div><div className="calendar-controls"><button className="icon-btn" aria-label={tr("14 hari sebelumnya")} onClick={() => setStart(start - 14 * DAY)}><ChevronLeft size={17}/></button><button className="text-btn" onClick={() => setStart(parseWita(dateWita(renderTime) + "T00:00"))}>{tr("Hari ini")}</button><button className="icon-btn" aria-label={tr("14 hari berikutnya")} onClick={() => setStart(start + 14 * DAY)}><ChevronRight size={17}/></button></div></div>{!data.units.length ? <Empty icon={CalendarDays} title={tr("Kalender menunggu unit pertama")} body={tr("Daftarkan motor, lalu buat booking untuk melihat jadwal setiap unit di sini.")}/> : <div className="calendar-scroll"><div className="calendar-grid"><div className="calendar-corner">{tr("UNIT MOTOR")}</div>{days.map(t => <div className={`calendar-day ${dateWita(t) === dateWita(renderTime) ? "today" : ""}`} key={t}><strong>{new Date(t + 28800000).getUTCDate()}</strong><small>{new Intl.DateTimeFormat(language === "en" ? "en-GB" : "id-ID", { timeZone: "Asia/Makassar", weekday: "short" }).format(t)}</small></div>)}{data.units.map((u: Row) => <CalendarRow key={u.id} u={u} data={data} days={days} onOpen={onOpen}/>)}</div></div>}<div className="table-note"><InfoMark /><span>{tr("Booking terkonfirmasi dan rental berjalan mengunci jadwal dengan jeda persiapan 1 jam. Draft dan pembatalan tidak mengunci unit. Kondisi perawatan di kolom unit menunjukkan status sekarang.")}</span></div></section>; }
function CalendarRow({ u, data, days, onOpen }: {
    u: Row;
    data: Row;
    days: number[];
    onOpen: (b: Row) => void;
}) {const renderTime=useOpsClock(); const { t: tr, language, formatDate } = useLanguage(); return <><div className="calendar-unit"><strong>{u.code}</strong><small>{MODEL_NAMES[u.model]} · {u.plate || tr("Tanpa plat")}</small>{u.state !== "ready" && <Badge status={u.state}/>}</div>{days.map(t => { const bookings = data.bookings.filter((b: Row) => ["pending_payment", "confirmed", "active", "completed"].includes(b.status) && JSON.parse(b.unit_ids).includes(u.id) && b.start_at < t + DAY && b.end_at > t); return <div className={`calendar-cell ${dateWita(t) === dateWita(renderTime) ? "today" : ""}`} key={t}>{bookings.map((b: Row) => <button key={b.id} className={`calendar-rental ${b.status}`} onClick={() => onOpen(b)} title={`${b.code} · ${formatDate(b.start_at)} — ${formatDate(b.end_at)}`}><span>{data.customers.find((c: Row) => c.id === b.customer_id)?.name || b.code}</span><small>{b.status === "active" ? tr("Disewa") : b.status === "completed" ? tr("Selesai") : "Booking"}</small></button>)}</div>; })}</>; }
function RevenueChart({ data, from, to }: {
    data: Row;
    from: string;
    to: string;
}) { const { t: tr, language, formatDate } = useLanguage(); const start = parseWita(from + "T00:00"), end = parseWita(to + "T00:00") + DAY, days = Math.max(1, Math.ceil((end - start) / DAY)), step = Math.max(1, Math.ceil(days / 31)); const rows = Array.from({ length: Math.ceil(days / step) }, (_, i) => { const at = start + i * step * DAY; const r = reportData(data.bookings, data.payments, at, Math.min(end, at + step * DAY),data.rental_extensions); return { at, cash: r.cash, service: r.service }; }); const max = Math.max(1, ...rows.flatMap(r => [Math.abs(r.cash), r.service])); return <section className="panel chart-panel"><PanelHeading title={tr("Perjalanan pendapatan")} subtitle={`${from} — ${to} · ${step > 1 ? tr("per {count} hari",{count:step}) : tr("per hari")}`}/><div className="chart-legend"><span><i className="dot teal"/>{tr("Uang sewa masuk")}</span><span><i className="dot mint"/>{tr("Alokasi sewa terjadwal")}</span></div><div className="chart" role="img" aria-label={tr("Grafik uang sewa masuk dan alokasi sewa terjadwal")}><div className="chart-y"><span>{idr(max)}</span><span>{idr(max / 2)}</span><span>Rp0</span></div><div className="chart-bars">{rows.map((r, i) => <div className="chart-column" key={r.at} title={tr("{date}: uang masuk {cash}, sewa {rental}",{date:dateWita(r.at),cash:idr(r.cash),rental:idr(r.service)})}><div className="bar-pair"><span className={`bar cash ${r.cash < 0 ? "negative" : ""}`} style={{ height: r.cash ? Math.max(3, Math.abs(r.cash) / max * 150) : 0 }}/><span className="bar service" style={{ height: r.service ? Math.max(3, r.service / max * 150) : 0 }}/></div><small>{i === 0 || i === rows.length - 1 || i % Math.max(1, Math.ceil(rows.length / 7)) === 0 ? dateWita(r.at).slice(8) : ""}</small></div>)}</div></div>{!rows.some(r => r.cash || r.service) && <p className="chart-empty">{tr("Belum ada transaksi atau rental terjadwal dalam periode ini.")}</p>}</section>; }
